// Two isolated mechanisms; fixed exogenous Gaussian banks.
#include "asymmetric_readout.cpp"
extern "C" void regime_stress(int n,int na,int nq,const double*means,const double*sd,const double*b,const double*q,double r,double w,const double*m,const double*nodes,const double*weights,double*out){
 auto worker=[&](int begin,int end){for(int i=begin;i<end;++i){double*o=out+uint64_t(i)*na*2;for(int j=0;j<2*na;++j)o[j]=0;for(int s=0;s<nq;++s){double As=std::exp(b[0]*(means[2*i]+sd[0]*nodes[s])-.5*b[0]*b[0]*q[0]);for(int f=0;f<nq;++f){double Af=std::exp(b[1]*(means[2*i+1]+sd[1]*nodes[f])-.5*b[1]*b[1]*q[1]),A=(1-r)*As+r*Af,wt=weights[s]*weights[f];for(int a=0;a<na;++a){double ratio=((1-w)+w*A)/((1-w)*m[2*a+1]+w*A*m[2*a]);o[2*a]+=wt*(1-w)*ratio;o[2*a+1]+=wt*w*A*ratio;}}}}};std::vector<std::thread>threads;for(int j=0;j<4;++j)threads.emplace_back(worker,n*j/4,n*(j+1)/4);for(auto&t:threads)t.join();
}
extern "C" void targeted_stock(int nt,int pairs,int nd,int nb,int ne,int na,const int*tr,const double*dec,const double*root,const double*cross,const double*bmean,const double*broot,const double*diffusion,const double*mean,const double*proj,const double*time,const double*dt,const int*seg,const int*coarse,const int*reference,const int*expiry,const double*norm,const double*p,const double*models,const double*alpha,const int*mode,const double*moments,double scale,uint64_t seed,double*out){
 Model m(models);int oldb=nb-2;std::vector<double>ds(nt),df(nt),ns(nt),nf(nt),cs(nt),cf(nt),rs(nt),rf(nt),qs(nt),qf(nt);for(int t=0;t<nt;++t){double h=dt[t];ds[t]=std::exp(-m.as*h);df[t]=std::exp(-m.af*h);ns[t]=std::sqrt(-std::expm1(-2*m.as*h));nf[t]=std::sqrt(-std::expm1(-2*m.af*h));rs[t]=std::sqrt(residual(m.as,h));rf[t]=std::sqrt(residual(m.af,h));cs[t]=std::sqrt(h-rs[t]*rs[t]);cf[t]=std::sqrt(h-rf[t]*rf[t]);qs[t]=-std::expm1(-2*m.as*time[t]);qf[t]=-std::expm1(-2*m.af*time[t]);}
 auto worker=[&](int begin,int end){for(int i=begin;i<end;++i){std::vector<double>s(nd,0),next(nd),z(nd+1),extra(oldb-1),db(nb),direction(nb),helddir(2*nb),logs(4*na,0),hold(2*na);double zs=0,zf=0,refv[2]={},reflog[2]={};
 for(int t=0;t<nt;++t){int transition=tr[t];uint64_t pathstep=uint64_t(t)*pairs+i,k=pathstep*(nd+3);for(int j=0;j<nd+1;++j)z[j]=gaussian(seed,k+j);double dw=std::sqrt(dt[t])*z[0],es=gaussian(seed,k+nd+1),ef=gaussian(seed,k+nd+2);db[0]=dw;db[nb-2]=cs[t]*es+rs[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*pathstep);db[nb-1]=cf[t]*ef+rf[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*pathstep+1);for(int j=0;j<oldb-1;++j)extra[j]=gaussian(seed^UINT64_C(0x78d904ef6038fb35),pathstep*(oldb-1)+j);
 const double*bm=bmean+uint64_t(transition)*(oldb-1)*nd,*br=broot+uint64_t(transition)*(oldb-1)*(oldb-1);for(int j=0;j<oldb-1;++j){double v=0;for(int l=0;l<nd;++l)v+=bm[j*nd+l]*z[l+1];for(int l=0;l<oldb-1;++l)v+=br[j*(oldb-1)+l]*extra[l];db[j+1]=v;}
 double fixedshock=.6*dw-.8*(std::sqrt(1-m.r)*db[nb-2]+std::sqrt(m.r)*db[nb-1]),pr[3]={};for(int j=0;j<nd;++j)for(int c=0;c<3;++c)pr[c]+=proj[c*nd+j]*s[j];
 for(int anti=0;anti<2;++anti){double sign=anti?-1:1,C=mean[3*t]+sign*pr[0],Y=mean[3*t+1]+sign*pr[1],F=mean[3*t+2]+sign*pr[2],eta=p[0]*C+p[1]*std::pow(Y-p[2],2)+p[3]*std::pow(F-p[4],2),old=G(eta,p)*std::exp(-norm[t]),As=std::exp(sign*m.bs*zs-.5*m.bs*m.bs*qs[t]),Af=std::exp(sign*m.bf*zf-.5*m.bf*m.bf*qf[t]),A=(1-m.r)*As+m.r*Af,H=(1-m.w)*old+m.w*A,l=sp(-sign*pr[1]/scale),sig=1/(1+std::exp(p[6]*(eta-p[5]))),grad[3]={p[0],2*p[1]*(Y-p[2]),2*p[3]*(F-p[4])};double length=0;
 for(int j=0;j<nb;++j){double v=0;if(j<oldb){for(int c=0;c<3;++c)v+=2*(1-m.w)*old*sig*grad[c]*diffusion[c*oldb+j];}else if(j==nb-2)v=m.w*(1-m.r)*m.bs*std::sqrt(2*m.as)*As;else v=m.w*m.r*m.bf*std::sqrt(2*m.af)*Af;direction[j]=-v;length+=v*v;}length=std::sqrt(length);if(length>1e-100){for(double&v:direction)v/=length;}else{std::fill(direction.begin(),direction.end(),0);direction[0]=.6;direction[nb-2]=-.8*std::sqrt(1-m.r);direction[nb-1]=-.8*std::sqrt(m.r);}
 if(coarse[t])for(int j=0;j<nb;++j)helddir[anti*nb+j]=direction[j];double adaptive[2]={0,0};for(int j=0;j<nb;++j){adaptive[0]+=helddir[anti*nb+j]*db[j];adaptive[1]+=direction[j]*db[j];}
 for(int a=0;a<na;++a){const double*x=models+23*a;double response=H;if(mode[a]==2){const double*mm=moments+(uint64_t(t)*na+a)*2;response=H*std::exp(alpha[a]*l)*((1-m.w)+m.w*A)/((1-m.w)*mm[1]+m.w*A*mm[0]);}double v=m.f+(.2-m.f)*x[seg[t]]*response;if(coarse[t])hold[anti*na+a]=v;for(int grid=0;grid<2;++grid){double vv=grid?v:hold[anti*na+a],shock=mode[a]==1?adaptive[grid]:fixedshock;logs[(anti*na+a)*2+grid]+=-.5*vv*dt[t]+std::sqrt(vv)*sign*shock;}}
 if(reference[t])refv[anti]=m.f+(.2-m.f)*models[seg[t]]*((1-m.w)+m.w*A);reflog[anti]+=-.5*refv[anti]*dt[t]+std::sqrt(refv[anti])*sign*fixedshock;
 if(expiry[t]>=0){double*o=out+((uint64_t(anti*pairs+i)*ne+expiry[t])*(na+1)*2);for(int a=0;a<na;++a)for(int grid=0;grid<2;++grid)o[2*a+grid]=std::exp(logs[(anti*na+a)*2+grid]);o[2*na]=o[2*na+1]=std::exp(reflog[anti]);}
 }
 const double*r=root+uint64_t(transition)*nd*nd;for(int j=0;j<nd;++j){double v=cross[transition*nd+j]*dw;for(int l=0;l<nd;++l)v+=r[j*nd+l]*z[l+1];next[j]=dec[transition*nd+j]*s[j]+v;}s.swap(next);zs=ds[t]*zs+ns[t]*es;zf=df[t]*zf+nf[t]*ef;
 }}};std::vector<std::thread>threads;for(int j=0;j<4;++j)threads.emplace_back(worker,pairs*j/4,pairs*(j+1)/4);for(auto&t:threads)t.join();
}
